<?php
namespace App\Console\Commands;use Illuminate\Console\Command;use Illuminate\Support\Facades\DB;use Illuminate\Support\Facades\Schema;use Illuminate\Support\Facades\Storage;use Illuminate\Support\Str;
class ExpireHrReportArtifacts extends Command{protected$signature='hr:expire-report-artifacts {--commit}';protected$description='Preview or remove expired private HR report artifacts';public function handle():int{if(!Schema::hasTable('hr_report_runs'))return self::SUCCESS;$commit=(bool)$this->option('commit');$count=0;DB::table('hr_report_runs')->where('status','completed')->whereNotNull('artifact_expires_at')->where('artifact_expires_at','<=',now())->chunkById(100,function($rows)use($commit,&$count){foreach($rows as$run){$count++;if(!$commit)continue;if($run->artifact_path&&Storage::disk($run->artifact_disk)->exists($run->artifact_path))Storage::disk($run->artifact_disk)->delete($run->artifact_path);DB::transaction(function()use($run){DB::table('hr_report_runs')->where('id',$run->id)->update(['status'=>'expired','artifact_path'=>null,'updated_at'=>now()]);DB::table('hr_report_delivery_events')->insert(['id'=>(string)Str::uuid(),'report_run_id'=>$run->id,'channel'=>'system','event_type'=>'expired','artifact_checksum'=>$run->artifact_checksum,'actor_user_id'=>config('hr.system_user_id'),'occurred_at'=>now()]);});}});$this->info(($commit?'Expired ':'Would expire ').$count.' HR report artifact(s).');return self::SUCCESS;}}
